<template><section class="responsible-party"><h3>{{ ft('Responsible billing party') }}</h3><p v-if="loading" role="status">{{ ft('Loading billing contact…') }}</p><p v-if="error" role="alert">{{ ft(error) }}</p><p v-if="message" role="status">{{ ft(message) }}</p><p v-if="!loading && !party && !hasAssignedShare">{{ ft('To do: select who is responsible for bills and balances.') }}</p><p v-if="!party && hasAssignedShare">{{ ft('Your existing balances already have assigned payers. You can optionally select a billing contact for future bills below.') }}</p><p v-if="party"><strong>{{ party.contact?.fullName || selectedAccount?.name }}</strong><span v-if="party.contact?.email"> · {{ party.contact.email }}</span><span v-if="party.contact?.phone"> · {{ party.contact.phone }}</span></p><form @submit.prevent="save"><label>{{ ft('Who should receive billing balances?') }}<select v-model="selection" required><option value="">{{ ft('Select a responsible party') }}</option><option v-for="account in accounts" :key="account.id" :value="String(account.id)">{{ account.name }} · {{ ft(account.relationship) }}</option><option value="other">{{ ft('Someone else') }}</option></select></label><template v-if="selection==='other'"><label v-for="field in contactFields" :key="field.key">{{ ft(field.title) }}<input v-model="contact[field.key]" :type="field.key==='email'?'email':field.key==='phone'?'tel':'text'" required maxlength="255" /></label></template><p>{{ ft('Selecting a billing contact does not authorize card charges or give access to private records.') }}</p><button :disabled="busy || !selection">{{ ft(busy?'Saving…':'Save responsible party') }}</button></form></section></template>
<script setup>
import {computed,ref,watch,onBeforeUnmount} from 'vue';import api from '../../services/api';import {useFamilyLocale} from '../../composables/useFamilyLocale';
const {ft}=useFamilyLocale();const props=defineProps({clientId:[String,Number],agencyId:[String,Number],staff:Boolean,hasAssignedShare:Boolean});const emit=defineEmits(['saved']);
const party=ref(null),accounts=ref([]),selection=ref(''),contact=ref({}),loading=ref(false),busy=ref(false),error=ref(''),message=ref('');let seq=0;
const contactFields=[{key:'fullName',title:'Full name'},{key:'email',title:'Email'},{key:'phone',title:'Phone'},{key:'address',title:'Mailing address'},{key:'city',title:'City'},{key:'state',title:'State'},{key:'postalCode',title:'Postal code'}];
const selectedAccount=computed(()=>accounts.value.find(account=>Number(account.id)===Number(party.value?.userId)));
const endpoint=()=>`/family-billing/${props.staff?'account/':''}clients/${props.clientId}/${props.staff?'settings':'responsible-party'}`;
async function load(){const own=++seq;party.value=null;accounts.value=[];selection.value='';contact.value={};error.value='';if(!props.clientId||!props.agencyId)return;loading.value=true;try{const {data}=await api.get(endpoint(),{params:{agencyId:props.agencyId}});if(own!==seq)return;party.value=data.responsibleParty;accounts.value=data.accounts;selection.value=party.value?.kind==='other'?'other':party.value?.userId?String(party.value.userId):'';contact.value={...(party.value?.contact||{})};}catch(e){if(own===seq)error.value=e.response?.data?.error?.message||'The billing contact could not be loaded.';}finally{if(own===seq)loading.value=false;}}
async function save(){if(busy.value)return;const own=seq;busy.value=true;error.value='';message.value='';try{await api.put(`/family-billing/${props.staff?'account/':''}clients/${props.clientId}/responsible-party`,{agencyId:props.agencyId,revision:party.value?.revision||0,party:{kind:selection.value==='other'?'other':'account',userId:selection.value==='other'?null:Number(selection.value),contact:contact.value}});if(own!==seq)return;await load();message.value='Responsible billing party saved.';emit('saved');}catch(e){if(own===seq)error.value=e.response?.data?.error?.message||'The billing contact could not be saved.';}finally{busy.value=false;}}
watch(()=>[props.clientId,props.agencyId],load,{immediate:true});onBeforeUnmount(()=>{seq++;});
</script>
<style scoped>.responsible-party{padding:18px;border:1px solid var(--border,#d5e1ed);border-radius:10px;margin:16px 0}.responsible-party form{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.responsible-party label{display:grid;gap:6px}.responsible-party input,.responsible-party select{padding:10px;font:inherit;min-width:0;max-width:100%;border:1px solid #b6c9dc;border-radius:6px}.responsible-party form p{grid-column:1/-1}.responsible-party button{padding:10px;font:inherit}.responsible-party [role=alert]{color:#a12727}</style>
